import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type ChampagneSwayProps = Record<string, any>;

const ChampagneSway: React.FC<ChampagneSwayProps> = ({
  backgroundColor = "#0e0e11",
  transparentBackground = false,
  durationInSeconds = 3,
  glassOutlineColor = "#ffffff",
  champagneColor = "#F4D068",
  surfaceAccentColor = "#D9AE3E",
  bubbleColor = "rgba(255, 255, 255, 0.6)",
  bubbleDensity = 25,
}) => {
  {/* Load Google Fonts - kept for structural compliance even if no text is rendered */}
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parse background color
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Timing logic
  const totalFrames = durationInSeconds * fps;
  const outroStart = totalFrames - 40;

  // Y-Axis Spring Logic (Entry from bottom, Exit to bottom)
  const entryY = spring({
    fps,
    frame,
    config: { damping: 14, stiffness: 70 },
  });

  const exitY = spring({
    fps,
    frame: frame - outroStart,
    config: { damping: 14, stiffness: 70 },
  });

  // Calculate scaling to ensure the 600px tall glass looks perfect on any canvas
  const glassNativeHeight = 600;
  const targetScale = (height * 0.6) / glassNativeHeight;
  const dropDistance = height / targetScale + 200; // Calculate distance in unscaled pixels

  // Position interpolation
  const currentY =
    interpolate(entryY, [0, 1], [dropDistance, 0], { extrapolateRight: "clamp" }) +
    interpolate(exitY, [0, 1], [0, dropDistance], { extrapolateRight: "clamp" });

  // Damped Harmonic Oscillator Math for natural sway
  const getSway = (f: number, amp: number, freq: number = 0.22, decay: number = 15) => {
    if (f < 0) return 0;
    return Math.sin(f * freq) * amp * Math.exp(-f / decay);
  };

  // Glass Container Sway
  const introSway = getSway(frame, 45);
  // Outro sway triggers at outroStart with an opposite initial direction
  const outroSway = getSway(frame - outroStart, -45);
  const glassAngle = introSway + outroSway;

  // Liquid Physics Math
  // The liquid slosh intentionally lags behind the glass movement by ~4 frames
  const lagFrames = 4;
  const introSlosh = getSway(frame - lagFrames, 30);
  const outroSlosh = getSway(frame - outroStart - lagFrames, -30);
  
  // The global liquid angle is the net result of the slosh logic.
  const liquidGlobalAngle = introSlosh + outroSlosh;
  
  // Because the liquid is drawn *inside* the rotating glass container, 
  // we must counter-rotate it to simulate staying horizontally leveled (plus slosh offset).
  const liquidRelativeAngle = liquidGlobalAngle - glassAngle;

  // Bubble generation based on density prop
  const bubbles = React.useMemo(() => {
    return Array.from({ length: bubbleDensity }).map((_, i) => {
      // Deterministic randomness
      const offset = i * 73;
      const speed = 1.2 + (i % 3) * 0.4;
      // Spread X horizontally across the liquid
      const xPos = 125 + (i % 50); 
      // Individual timeline per bubble
      const localFrame = frame * speed + offset;
      
      // Bubbles rise from bottom of the bowl (Y=350) upwards
      const y = 350 - (localFrame % 250); 
      const size = 1 + (i % 3);
      // Gentle horizontal wobble as they rise
      const x = xPos + Math.sin(localFrame * 0.1) * 3;

      return (
        <circle
          key={i}
          cx={x}
          cy={y}
          r={size}
          fill={bubbleColor}
        />
      );
    });
  }, [bubbleDensity, frame, bubbleColor]);

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter", transition: "none" }}>
      <div
        style={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          width: "100%",
          height: "100%",
          transition: "none",
        }}
      >
        <div
          style={{
            width: 300,
            height: 600,
            transform: `scale(${targetScale}) translateY(${currentY}px) rotate(${glassAngle}deg)`,
            // Pivot rotation exactly around the center base of the glass
            transformOrigin: "150px 550px",
            transition: "none",
          }}
        >
          <svg
            width="300"
            height="600"
            viewBox="0 0 300 600"
            style={{ overflow: "visible", transition: "none" }}
          >
            <defs>
              {/* Perfectly traces the inner volume of the glass bowl */}
              <clipPath id="bowlClip">
                <path d="M 112 55 C 112 245, 148 325, 150 345 C 152 325, 188 245, 188 55 Z" />
              </clipPath>
              {/* Acts as the dynamic liquid surface horizon line */}
              <clipPath id="surfaceClip">
                <rect
                  x="-200"
                  y="150"
                  width="700"
                  height="500"
                  transform={`rotate(${liquidRelativeAngle}, 150, 150)`}
                />
              </clipPath>
            </defs>

            {/* Render Liquid inside the intersection of the bowl shape and the rotated surface horizon */}
            <g clipPath="url(#bowlClip)">
              <g clipPath="url(#surfaceClip)">
                {/* Main Champagne Body */}
                <rect x="0" y="0" width="300" height="600" fill={champagneColor} />
                
                {/* Surface Meniscus Line */}
                <line
                  x1="-200"
                  y1="150"
                  x2="500"
                  y2="150"
                  stroke={surfaceAccentColor}
                  strokeWidth="4"
                  transform={`rotate(${liquidRelativeAngle}, 150, 150)`}
                />
                
                {/* Bubbles physically stop cleanly at the clip surface */}
                {bubbles}
              </g>
            </g>

            {/* Glass Construction Layers */}
            {/* Back Lip */}
            <path
              d="M 110 50 A 40 10 0 0 1 190 50"
              stroke={glassOutlineColor}
              fill="none"
              strokeWidth="3"
              opacity="0.4"
            />
            
            {/* Main Bowl and Stem */}
            <path
              d="M 110 50 C 110 250, 148 330, 150 350 L 150 550 M 190 50 C 190 250, 152 330, 150 350"
              stroke={glassOutlineColor}
              fill="none"
              strokeWidth="4"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            
            {/* 3D Cylindrical Highlight Curve */}
            <path
              d="M 115 60 C 115 240, 148 320, 149 340"
              stroke="#ffffff"
              strokeWidth="4"
              opacity="0.25"
              fill="none"
              strokeLinecap="round"
            />
            
            {/* Front Lip */}
            <path
              d="M 110 50 A 40 10 0 0 0 190 50"
              stroke={glassOutlineColor}
              fill="none"
              strokeWidth="3"
            />
            
            {/* Elegant Elliptical Base */}
            <path
              d="M 100 550 A 50 10 0 0 0 200 550 A 50 10 0 0 0 100 550"
              stroke={glassOutlineColor}
              fill={glassOutlineColor}
              strokeWidth="2"
              opacity="0.85"
            />
          </svg>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default ChampagneSway;